// ---------------------------------------------------------------------------

/**
 * Every evaluation this detector performs, fired or not (mt#3583, ADR-032 §D2).
 *
 * **Deliberately not the `*-calibration.jsonl` log.** `coverage-receipt.ts`
 * treats the existence of a calibration record as evidence the detector FIRED —
 * that is the whole live-vs-dormant signal it computes. Writing non-fire records
 * into that log would report a detector as covered on turns where it stayed
 * silent, breaking a shipped gate to feed a new consumer. The filename also
 * deliberately avoids the `-calibration` suffix, because
 * `scripts/check-coverage-receipts.ts` discovers its inputs by globbing
 * `.minsky/*-calibration.jsonl`.
 *
 * What this stream is for: the tuning loop needs to know whether guidance
 * CHANGED anything, and that is unanswerable from fires alone — a corpus of
 * fires can say "it happened again" but never "it stopped happening."
 *
 * mt#3745: the logical stream NAME, not a path — `logEvaluationRecord` /
 * `evaluationLogPath` derive `.minsky/<name>-evaluations.jsonl` from it, the
 * same name/path split the registry's `calibrationLog` uses.
 */
const EVALUATION_LOG_NAME = "silent-stretch";

/**
 * Append one evaluation record. Fail-open and never throws, matching
 * `appendCalibrationRecord` above: a measurement stream must never be able to
 * break the guard whose behavior it measures.
 */
export function appendEvaluationRecord(cwd: string, record: Record<string, unknown>): void {
  // mt#3745: `cwd` is the guard's raw input cwd — a FALLBACK, never a root.
  logEvaluationRecord(EVALUATION_LOG_NAME, record, { fallbackCwd: cwd });
}

/**
 * Bounded-tail read of the evaluation log, for the same-turn dedupe below.
 *
 * mt#3745: this READER had the same cwd-rooting defect as the writer, and it
 * matters independently — reading a cwd-rooted path inside a session workspace
 * dedupes against the wrong (usually empty) log, so the dedupe silently stops
 * deduping exactly where the stray writes were landing.
 */
export function readEvaluationLogText(cwd: string): string | undefined {
  return readLogTailText(evaluationLogPath(EVALUATION_LOG_NAME, { fallbackCwd: cwd }));
}

/** Injectable overrides for `run()` — tests substitute in-memory fakes for both real-IO seams (`custom/no-real-fs-in-tests`). */
export interface RunDeps {
  /** Defaults to the real `readCalibrationLogText`. Used by the dedupe check. */
  readCalibrationLogTextFn?: (cwd: string) => string | undefined;
  /** Defaults to the real `readEvaluationLogText`. Used by the evaluation-stream dedupe. */
  readEvaluationLogTextFn?: (cwd: string) => string | undefined;
  /** Defaults to the real `appendEvaluationRecord`. */
  appendEvaluationRecordFn?: (cwd: string, record: Record<string, unknown>) => void;
}

// ---------------------------------------------------------------------------
// Dispatcher-compatible pure function (ADR-028 D1/D2)
// ---------------------------------------------------------------------------

/**
 * Guard-dispatcher entry point. Uses `resolveParentTranscriptLines` (mt#3003)
 * instead of trusting `ctx.transcriptLines` (D6) as-is — when this
 * conversation has dispatched subagents, `ctx.transcriptLines` is a flat
 * concatenation of the parent transcript with every sibling subagent
 * transcript (mt#2637), and turn-boundary extraction over that flattened
 * array can anchor inside a SUBAGENT's own (static) transcript instead of
 * the live parent conversation — freezing the measured turn and re-logging
 * the identical record on every subsequent firing (the actual root cause of
 * the "stale turn re-measurement" bug; see `transcript.ts`'s
 * `resolveParentTranscriptLines` doc comment for the full mechanism and the
 * investigation that found it). Before logging, also checks the
 * `buildTurnAnchor` dedupe key (defense-in-depth per the mt#3003 spec) so a
 * turn already logged for this session — anchoring bug aside — is never
 * re-logged. On a match this returns BOTH a `calibration` record (which the
 * dispatcher forwards to `logCalibrationRecord` per this guard's
 * `calibrationLog: "silent-stretch"` registration) AND, since mt#3399 flipped
 * `INJECTION_ENABLED`, an `additionalContext` reminder. The calibration field
 * is set first and unconditionally, so the measurement stream survives the
 * graduation.
 */
export function run(
  input: ClaudeHookInput,
  ctx: DispatchContext,
  deps: RunDeps = {}
): GuardOutcome | null {
  const overrideVal = process.env[OVERRIDE_ENV_VAR];
  const isOverride =
    overrideVal === "1" ||
    overrideVal?.toLowerCase() === "true" ||
    overrideVal?.toLowerCase() === "yes";
  if (isOverride) {
    return {
      auditLines: [
        `[silent-stretch-detector] OVERRIDE: ack=${overrideVal} session=${input.session_id ?? "unknown"} ts=${new Date().toISOString()}\n`,
      ],
    };
  }

  if (!input.transcript_path) return null;
  const readCalibrationLogTextFn = deps.readCalibrationLogTextFn ?? readCalibrationLogText;

  // `ctx.transcriptLines` is PARENT-ONLY by construction as of mt#3293 — the dispatcher
  // resolves it through `resolveParentTranscriptLines` for every guard. This used to call
  // that resolver itself (mt#3003, when only this detector and wall-of-text had the fix);
  // doing so now would re-read and re-parse the parent transcript to arrive at the array
  // already in hand. One mechanism, at the seam that owns it.
  const lines = ctx.transcriptLines;
  if (lines.length === 0) return null;

  let turnLines: TranscriptLine[];
  try {
    turnLines = extractLastAssistantTurn(lines, ctx.recordedAnchor);
  } catch {
    return null;
  }
  if (turnLines.length === 0) return null;

  let measurement: SilentStretchMeasurement;
  let boundaries: TurnBoundaryTimestamps;
  try {
    boundaries = findTurnBoundaryTimestamps(lines);
    measurement = measureSilentStretch(turnLines, boundaries.turnStartTimestamp);
  } catch (err) {
    process.stderr.write(
      `[silent-stretch-detector] Measurement error: ${err instanceof Error ? err.message : String(err)}\n`
    );
    return null;
  }

  const turnAnchor = buildTurnAnchor(boundaries);
  // One clock read for BOTH records (mt#4018). Reading `Date.now()` separately
  // per record would let the evaluation and calibration rows for the same
  // firing disagree by however long the dedupe reads took, which is exactly
  // the kind of drift that makes a delta un-auditable later.
  const firedAt = new Date().toISOString();
  const stalenessMinutes = computeStalenessMinutes(boundaries.turnEndTimestamp, firedAt);

  // mt#3583: record the measurement whether or not it matched. A fire-only
  // stream can express "it happened again" but never "it stopped happening,"
  // and the tuning loop needs both — see EVALUATION_LOG's doc comment. Deduped
  // on the same turn anchor as the calibration record below, for the same
  // reason: an unchanged turn re-measured on a later prompt would otherwise
  // append a duplicate, and a duplicate of a FIRE reads downstream as the guard
  // firing twice — turning one fire into a false `dismissed`.
  const appendEvaluation = deps.appendEvaluationRecordFn ?? appendEvaluationRecord;
  const readEvaluationLogTextFn = deps.readEvaluationLogTextFn ?? readEvaluationLogText;
  // A record with no session id is skipped entirely rather than written
  // undeduped (PR #2569 R1). `sessionHasLoggedKey` returns false whenever the
  // session id is falsy — it cannot match a record it cannot key — so emitting
  // here would append on EVERY evaluation with no upper bound. Skipping loses
  // nothing: the labeler sequences within a session, so a record with no
  // session id could never be ordered against anything anyway.
  const hasSessionId = typeof input.session_id === "string" && input.session_id.trim() !== "";
  if (
    turnAnchor &&
    hasSessionId &&
    !sessionHasLoggedKey(
      readEvaluationLogTextFn(input.cwd),
      input.session_id,
      "turnAnchor",
      turnAnchor
    )
  ) {
    appendEvaluation(input.cwd, {
      timestamp: firedAt,
      session_id: input.session_id,
      guardName: "silent-stretch-detector",
      turnAnchor,
      gapMinutes: measurement.gapMinutes,
      toolCallCount: measurement.toolCallCount,
      // Present on the NON-matched rows too, deliberately: the staleness
      // distribution is a property of when this guard runs, not of whether it
      // fired, so a fire-only sample would be biased by construction.
      ...(stalenessMinutes !== undefined ? { stalenessMinutes } : {}),
      fired: measurement.matched,
    });
  }

  if (!measurement.matched) return null;
  if (
    turnAnchor &&
    sessionHasLoggedKey(
      readCalibrationLogTextFn(input.cwd),
      input.session_id,
      "turnAnchor",
      turnAnchor
    )
  ) {
    // mt#3003 defense-in-depth: a record for this exact turn anchor already
    // exists for this session — the anchoring fix above should make this
    // rare, but a genuinely-unchanged re-measurement (or a residual
    // contamination shape not yet covered) must still not re-log.
    return null;
  }

  const outcome: GuardOutcome = {
    calibration: {
      timestamp: firedAt,
      session_id: input.session_id,
      gapMinutes: Math.round(measurement.gapMinutes * 100) / 100,
      toolCallCount: measurement.toolCallCount,
      hadTextInTurn: measurement.hadTextInTurn,
      turnAnchor,
      ...(stalenessMinutes !== undefined ? { stalenessMinutes } : {}),
    },
  };

  if (INJECTION_ENABLED) {
    // Live since mt#3399. Note the ordering: `outcome.calibration` above is set
    // unconditionally and BEFORE this branch, so a graduated detector keeps
    // feeding the calibration log that measures it.
    outcome.additionalContext = buildInjectionReminder(measurement);
  }

  return outcome;
}

function buildInjectionReminder(measurement: SilentStretchMeasurement): string {
  return [
    "[silent-stretch-detector] Silent tool-only stretch detected (mt#2824).",
    "",
    `The prior turn ran ${measurement.toolCallCount} consecutive tool call(s) and/or ` +
      `${measurement.gapMinutes.toFixed(1)} minute(s) of wall-clock silence without a ` +
      "user-visible status update.",
    "",
    "Emit a one-line heartbeat (current activity + health signal) at least every 10",
    "minutes or 15 tool calls during research/build chains.",
  ].join("\n");
}

// ---------------------------------------------------------------------------
// Standalone CLI entrypoint
// ---------------------------------------------------------------------------

export async function main(): Promise<void> {
  const capInfo = readHostCap("silent-stretch-detector.ts", undefined, {
    events: ["UserPromptSubmit"],
  });
  if (capInfo.warning) {
    process.stderr.write(`[silent-stretch-detector] ${capInfo.warning}\n`);
  }
  const budgets = deriveBudgets(capInfo.hostCapSec);
  const overallDeadline = Date.now() + budgets.overallBudgetMs;

  const overrideVal = process.env[OVERRIDE_ENV_VAR];
  const isOverride =
    overrideVal === "1" ||
    overrideVal?.toLowerCase() === "true" ||
    overrideVal?.toLowerCase() === "yes";

  let input: ClaudeHookInput;
  try {
    input = await readInput<ClaudeHookInput>();
  } catch {
    process.exit(0);
  }

  if (isOverride) {
    const ts = new Date().toISOString();
    process.stdout.write(
      `[silent-stretch-detector] OVERRIDE: ack=${overrideVal} session=${input.session_id ?? "unknown"} ts=${ts}\n`
    );
    process.exit(0);
  }

  const transcriptPath = input.transcript_path;
  if (!transcriptPath) {
    process.exit(0);
  }

  if (Date.now() >= overallDeadline) {
    process.stderr.write(
      `[silent-stretch-detector] budget exhausted before transcript read — skipping\n`
    );
    process.exit(0);
  }

  // PR #2175 R1: mirrors run()'s cross-transcript-contamination guard
  // (resolveParentTranscriptLines) — a bare parseTranscript(transcriptPath)
  // here would leave the standalone CLI path vulnerable to the same
  // stale-turn freeze the dispatcher path is guarded against, and
  // divergent from it besides.
  const lines = resolveParentTranscriptLinesForPath(transcriptPath, input.agent_id);
  if (lines.length === 0) {
    process.exit(0);
  }

  let turnLines: TranscriptLine[];
  try {
    turnLines = extractLastAssistantTurn(lines);
  } catch {
    process.exit(0);
  }

  if (turnLines.length === 0) {
    process.exit(0);
  }

  let measurement: SilentStretchMeasurement;
  let boundaries: TurnBoundaryTimestamps;
  try {
    boundaries = findTurnBoundaryTimestamps(lines);
    measurement = measureSilentStretch(turnLines, boundaries.turnStartTimestamp);
  } catch (err) {
    console.error(`[silent-stretch-detector] Measurement error: ${getLoggableErrorSummary(err)}`);
    process.exit(0);
  }

  if (!measurement.matched) {
    process.exit(0);
  }

  const turnAnchor = buildTurnAnchor(boundaries);
  if (Date.now() < overallDeadline) {
    // mt#3003: skip re-logging a turn already recorded for this session
    // (see run()'s equivalent check + this file's header comment).
    const alreadyLogged = turnAnchor
      ? sessionHasLoggedKey(
          readCalibrationLogText(input.cwd),
          input.session_id,
          "turnAnchor",
          turnAnchor
        )
      : false;
    if (!alreadyLogged) {
      // Same shape as run()'s calibration record, including mt#4018's
      // `stalenessMinutes` — the two paths write the same log, so a field on
      // one and not the other would make the corpus non-uniform by writer.
      const firedAt = new Date().toISOString();
      const stalenessMinutes = computeStalenessMinutes(boundaries.turnEndTimestamp, firedAt);
      appendCalibrationRecord(input.cwd, {
        timestamp: firedAt,
        session_id: input.session_id,
        gapMinutes: Math.round(measurement.gapMinutes * 100) / 100,
        toolCallCount: measurement.toolCallCount,
        hadTextInTurn: measurement.hadTextInTurn,
        turnAnchor,
        ...(stalenessMinutes !== undefined ? { stalenessMinutes } : {}),
      });
    }
  }

  if (!INJECTION_ENABLED) {
    process.exit(0);
  }

  // Since mt#3399 this standalone path emits a HookOutput JSON on stdout where
  // it previously exited silently (PR #2457 R1 flagged the behavior change).
  // It has no registered consumer: `.claude/settings.json`'s UserPromptSubmit
  // block contains only `dispatch-userpromptsubmit.ts` and
  // `record-conversation-run-state.ts`, so the harness reaches this detector
  // through the dispatcher's in-process registry, never by executing this file.
  // main() therefore runs only when the file is invoked directly (manual
  // debugging), and the emitted shape is the same HookOutput the dispatcher
  // produces — so a direct invoker gets the documented contract, not a surprise.
  const reminder = buildInjectionReminder(measurement);
  const output: HookOutput = {
    hookSpecificOutput: {
      hookEventName: "UserPromptSubmit",
      additionalContext: reminder,
    },
  };
  process.stdout.write(JSON.stringify(output));
  process.exit(0);
}

// Entrypoint guard: only run main() when this file is invoked as a script —
// the dispatcher's dynamic `import("./silent-stretch-detector")` must NOT
// trigger it (mt#2835 — see auto-session-title.ts's header comment for the
// incident this convention prevents: an ungated module-level main() call
// re-entered an already-drained stdin and killed the whole dispatcher
// process mid-loop).
if (import.meta.main) {
  await main();
}
